INSERT INTO departments (id, name, capital, region, description, cover_image_url, map_x, map_y) VALUES ('granada', 'Granada', 'Granada', 'Pacífico', 'La Gran Sultana, ciudad colonial más antigua de América Central fundada en 1524. Sus calles adoquinadas y coloridas fachadas la convierten en joya del patrimonio arquitectónico.', 'https://images.unsplash.com/photo-1630773899830-15ae96bbd777?w=1200&h=700&fit=crop&auto=format', 205, 196) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, capital = EXCLUDED.capital, region = EXCLUDED.region, description = EXCLUDED.description, cover_image_url = EXCLUDED.cover_image_url, map_x = EXCLUDED.map_x, map_y = EXCLUDED.map_y;
INSERT INTO departments (id, name, capital, region, description, cover_image_url, map_x, map_y) VALUES ('leon', 'León', 'León', 'Pacífico', 'Ciudad universitaria y capital cultural de Nicaragua. Cuna del poeta Rubén Darío y hogar de la Catedral más grande de América Central, Patrimonio de la Humanidad UNESCO.', 'https://images.unsplash.com/photo-1655346934940-b39b2924091f?w=1200&h=700&fit=crop&auto=format', 95, 148) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, capital = EXCLUDED.capital, region = EXCLUDED.region, description = EXCLUDED.description, cover_image_url = EXCLUDED.cover_image_url, map_x = EXCLUDED.map_x, map_y = EXCLUDED.map_y;
INSERT INTO departments (id, name, capital, region, description, cover_image_url, map_x, map_y) VALUES ('managua', 'Managua', 'Managua', 'Pacífico', 'Capital de Nicaragua y su ciudad más grande. Centro político, económico y cultural del país, a orillas del Lago Xolotlán con una historia marcada por terremotos y resurgimiento.', 'https://images.unsplash.com/photo-1590856029192-284cc8461706?w=1200&h=700&fit=crop&auto=format', 145, 165) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, capital = EXCLUDED.capital, region = EXCLUDED.region, description = EXCLUDED.description, cover_image_url = EXCLUDED.cover_image_url, map_x = EXCLUDED.map_x, map_y = EXCLUDED.map_y;
INSERT INTO departments (id, name, capital, region, description, cover_image_url, map_x, map_y) VALUES ('masaya', 'Masaya', 'Masaya', 'Pacífico', 'Capital del folklore y la artesanía nicaragüense. Sede del único volcán activo del mundo con laguna de lava permanentemente visible y el mercado artesanal más grande de Centroamérica.', 'https://images.unsplash.com/photo-1675701142610-5d40c754a3b6?w=1200&h=700&fit=crop&auto=format', 168, 185) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, capital = EXCLUDED.capital, region = EXCLUDED.region, description = EXCLUDED.description, cover_image_url = EXCLUDED.cover_image_url, map_x = EXCLUDED.map_x, map_y = EXCLUDED.map_y;
INSERT INTO departments (id, name, capital, region, description, cover_image_url, map_x, map_y) VALUES ('rivas', 'Rivas', 'Rivas', 'Pacífico', 'Puerta de entrada al Lago Nicaragua y la Isla de Ometepe. Hogar de las playas de San Juan del Sur y corredor bioceánico entre el Pacífico y el Caribe.', 'https://images.unsplash.com/photo-1710788206590-a8bbd6007e12?w=1200&h=700&fit=crop&auto=format', 138, 245) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, capital = EXCLUDED.capital, region = EXCLUDED.region, description = EXCLUDED.description, cover_image_url = EXCLUDED.cover_image_url, map_x = EXCLUDED.map_x, map_y = EXCLUDED.map_y;
INSERT INTO departments (id, name, capital, region, description, cover_image_url, map_x, map_y) VALUES ('matagalpa', 'Matagalpa', 'Matagalpa', 'Norte', 'La Perla del Septentrión. Ciudad de neblina y café entre bosques nubosos, conocida por su producción de café Gourmet de exportación mundial y sus reservas naturales vírgenes.', 'https://images.unsplash.com/photo-1590856028965-5683c4b48ad0?w=1200&h=700&fit=crop&auto=format', 242, 108) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, capital = EXCLUDED.capital, region = EXCLUDED.region, description = EXCLUDED.description, cover_image_url = EXCLUDED.cover_image_url, map_x = EXCLUDED.map_x, map_y = EXCLUDED.map_y;
INSERT INTO departments (id, name, capital, region, description, cover_image_url, map_x, map_y) VALUES ('esteli', 'Estelí', 'Estelí', 'Norte', 'Ciudad del tabaco y los puros finos, conocida mundialmente por producir algunos de los mejores cigarros del planeta. Sede de la Reserva Natural Miraflor y el Cañón de Somoto.', 'https://images.unsplash.com/photo-1590856029192-284cc8461706?w=1200&h=700&fit=crop&auto=format', 168, 68) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, capital = EXCLUDED.capital, region = EXCLUDED.region, description = EXCLUDED.description, cover_image_url = EXCLUDED.cover_image_url, map_x = EXCLUDED.map_x, map_y = EXCLUDED.map_y;
INSERT INTO tourist_sites (id, department_id, name, category, description, history, cover_image_url, thumbnail_image_url, video_url, tags) VALUES ('ciudad-colonial-granada', 'granada', 'Ciudad Colonial de Granada', 'colonial', 'El corazón colonial de Nicaragua, con arquitecturas de estilo hispano-colonial del siglo XVI, plazas centenarias y la mítica Catedral de Granada.', 'Granada fue fundada en 1524 por Francisco Hernández de Córdoba, convirtiéndose en una de las primeras ciudades europeas establecidas en tierra firme del continente americano. Su posición estratégica junto al Gran Lago de Nicaragua le permitió prosperar como centro comercial y cultural durante el período colonial. La ciudad fue saqueada tres veces por piratas, entre ellos el famoso William Walker en 1856, quien ordenó incendiar la ciudad al retirarse, dejando el letrero ''Aquí fue Granada''. Reconstruida con determinación, hoy conserva uno de los conjuntos arquitectónicos coloniales mejor preservados de Centroamérica, con más de 180 edificios de valor histórico catalogados por el Instituto Nicaragüense de Cultura.', 'https://images.unsplash.com/photo-1630773899830-15ae96bbd777?w=900&h=550&fit=crop&auto=format', 'https://images.unsplash.com/photo-1630773899830-15ae96bbd777?w=500&h=300&fit=crop&auto=format', 'https://www.youtube.com/watch?v=hc-FoNOfCUQ', '{"Colonial","Arquitectura","Historia","Centro Histórico"}') ON CONFLICT (id) DO UPDATE SET department_id = EXCLUDED.department_id, name = EXCLUDED.name, category = EXCLUDED.category, description = EXCLUDED.description, history = EXCLUDED.history, cover_image_url = EXCLUDED.cover_image_url, thumbnail_image_url = EXCLUDED.thumbnail_image_url, video_url = EXCLUDED.video_url, tags = EXCLUDED.tags;
INSERT INTO tourist_sites (id, department_id, name, category, description, history, cover_image_url, thumbnail_image_url, video_url, tags) VALUES ('isletas-de-granada', 'granada', 'Isletas de Granada', 'turistico', 'Archipiélago de 365 islotes volcánicos en el Lago Cocibolca, formados por la erupción del Volcán Mombacho hace más de 10,000 años.', 'Las Isletas de Granada son 365 pequeños islotes dispersos en las aguas del Gran Lago de Nicaragua (Lago Cocibolca), frente a las costas de la ciudad de Granada. Se formaron hace aproximadamente 10,000 años cuando el Volcán Mombacho sufrió un colosal colapso volcánico que proyectó enormes bloques de roca al lago. Durante la época precolombina, estas islas fueron habitadas por grupos indígenas Chorotegas, quienes encontraron en ellas un refugio natural y un punto estratégico para la pesca y el comercio. Hoy en día, algunas isletas albergan residencias privadas, pequeños hoteles y restaurantes flotantes, mientras que otras están completamente vírgenes y sirven como refugio de vida silvestre.', 'https://images.unsplash.com/photo-1711377449741-b01fd2adcd82?w=900&h=550&fit=crop&auto=format', 'https://images.unsplash.com/photo-1711377449741-b01fd2adcd82?w=500&h=300&fit=crop&auto=format', 'https://www.youtube.com/watch?v=zr-4gNnUSxs', '{"Naturaleza","Lagos","Ecoturismo","Kayak"}') ON CONFLICT (id) DO UPDATE SET department_id = EXCLUDED.department_id, name = EXCLUDED.name, category = EXCLUDED.category, description = EXCLUDED.description, history = EXCLUDED.history, cover_image_url = EXCLUDED.cover_image_url, thumbnail_image_url = EXCLUDED.thumbnail_image_url, video_url = EXCLUDED.video_url, tags = EXCLUDED.tags;
INSERT INTO tourist_sites (id, department_id, name, category, description, history, cover_image_url, thumbnail_image_url, video_url, tags) VALUES ('convento-san-francisco', 'granada', 'Convento San Francisco', 'historico', 'El convento más antiguo de América Central, fundado en 1529, alberga el Museo de Arte Precolombino con más de 30 estatuas indígenas del siglo X.', 'El Convento y Museo San Francisco es el edificio religioso más antiguo de Nicaragua y uno de los más antiguos de América Central. Fue fundado por la Orden Franciscana en 1529, apenas cinco años después de la fundación de la ciudad de Granada. A lo largo de su historia, el convento ha servido como cuartel militar, hospital, sede universitaria y cárcel, reflejando las convulsiones históricas de Nicaragua. Fue incendiado en varias ocasiones, incluyendo el saqueo de William Walker en 1856. Su actual edificio data de la reconstrucción de 1867-1868. Hoy alberga el Museo de Arte Precolombino y Colonial, que exhibe más de 30 grandes estatuas de piedra provenientes de la Isla de Zapatera, datadas del período prehispánico entre los siglos X y XIV.', 'https://images.unsplash.com/photo-1584904558330-f9772a6778c5?w=900&h=550&fit=crop&auto=format', 'https://images.unsplash.com/photo-1584904558330-f9772a6778c5?w=500&h=300&fit=crop&auto=format', 'https://www.youtube.com/watch?v=mJfAu6g7Xc4', '{"Colonial","Museo","Arte Precolombino","Franciscanos"}') ON CONFLICT (id) DO UPDATE SET department_id = EXCLUDED.department_id, name = EXCLUDED.name, category = EXCLUDED.category, description = EXCLUDED.description, history = EXCLUDED.history, cover_image_url = EXCLUDED.cover_image_url, thumbnail_image_url = EXCLUDED.thumbnail_image_url, video_url = EXCLUDED.video_url, tags = EXCLUDED.tags;
INSERT INTO tourist_sites (id, department_id, name, category, description, history, cover_image_url, thumbnail_image_url, video_url, tags) VALUES ('catedral-leon', 'leon', 'Catedral de León', 'colonial', 'La Catedral Basílica de la Asunción de León, declarada Patrimonio de la Humanidad por UNESCO en 2011. La catedral más grande de América Central con 113 años de construcción.', 'La Catedral de León, formalmente conocida como Catedral Basílica de la Asunción de León, es considerada la catedral más grande de América Central. Su construcción comenzó en 1747 bajo el diseño del arquitecto guatemalteco Diego José de Porres, aunque existen tradiciones que indican que el plano original fue presentado a la corte española como si fuera de una catedral menor para obtener la aprobación real. La construcción se extendió por 113 años, finalizando en 1860. En sus bóvedas reposan los restos del poeta Rubén Darío, máximo exponente del modernismo literario hispanoamericano, y de otros próceres nicaragüenses. En 2011, la UNESCO la declaró Patrimonio de la Humanidad junto con las Ruinas de León Viejo.', 'https://images.unsplash.com/photo-1655346934940-b39b2924091f?w=900&h=550&fit=crop&auto=format', 'https://images.unsplash.com/photo-1655346934940-b39b2924091f?w=500&h=300&fit=crop&auto=format', 'https://www.youtube.com/watch?v=KSv6sLBHFpM', '{"UNESCO","Colonial","Catedral","Arquitectura Barroca"}') ON CONFLICT (id) DO UPDATE SET department_id = EXCLUDED.department_id, name = EXCLUDED.name, category = EXCLUDED.category, description = EXCLUDED.description, history = EXCLUDED.history, cover_image_url = EXCLUDED.cover_image_url, thumbnail_image_url = EXCLUDED.thumbnail_image_url, video_url = EXCLUDED.video_url, tags = EXCLUDED.tags;
INSERT INTO tourist_sites (id, department_id, name, category, description, history, cover_image_url, thumbnail_image_url, video_url, tags) VALUES ('leon-viejo', 'leon', 'León Viejo', 'historico', 'Ruinas arqueológicas de la primera ciudad colonial de Nicaragua, sepultada por el volcán Momotombo en 1610. Sitio UNESCO desde 2000.', 'León Viejo, oficialmente conocido como Ruinas de León Viejo, es el sitio arqueológico de la primera ciudad española fundada en Nicaragua, establecida en 1524 por Francisco Hernández de Córdoba a orillas del Lago Xolotlán. La ciudad prosperó como capital colonial durante casi un siglo, pero en 1610, una combinación de erupciones constantes del volcán Momotombo, terremotos y pestes llevaron a sus habitantes a abandonarla y trasladarse al actual emplazamiento de León. La ciudad quedó sepultada bajo capas de ceniza volcánica durante casi 350 años, hasta que excavaciones arqueológicas iniciadas en 1967 revelaron sus estructuras. En el año 2000, UNESCO declaró el sitio como Patrimonio de la Humanidad, reconociendo su valor como testimonio único de la vida colonial temprana en América.', 'https://images.unsplash.com/photo-1590856028965-5683c4b48ad0?w=900&h=550&fit=crop&auto=format', 'https://images.unsplash.com/photo-1590856028965-5683c4b48ad0?w=500&h=300&fit=crop&auto=format', 'https://www.youtube.com/watch?v=8pVZR7wr7nM', '{"UNESCO","Arqueología","Ruinas","Volcán Momotombo"}') ON CONFLICT (id) DO UPDATE SET department_id = EXCLUDED.department_id, name = EXCLUDED.name, category = EXCLUDED.category, description = EXCLUDED.description, history = EXCLUDED.history, cover_image_url = EXCLUDED.cover_image_url, thumbnail_image_url = EXCLUDED.thumbnail_image_url, video_url = EXCLUDED.video_url, tags = EXCLUDED.tags;
INSERT INTO tourist_sites (id, department_id, name, category, description, history, cover_image_url, thumbnail_image_url, video_url, tags) VALUES ('vieja-catedral-managua', 'managua', 'Vieja Catedral de Managua', 'historico', 'Imponente ruina de la Catedral de Santiago de Managua, dañada por el terremoto de 1972 y convertida en símbolo emblemático de la resiliencia nicaragüense.', 'La Antigua Catedral de Managua, formalmente conocida como Catedral de Santiago, fue construida entre 1928 y 1938 en estilo neoclásico romano. Por décadas fue el centro espiritual de la capital nicaragüense. El devastador terremoto de 1972, que destruyó gran parte de Managua, dañó severamente sus estructuras internas. Aunque su exterior permaneció relativamente intacto, los ingenieros determinaron que era demasiado peligrosa para continuar siendo utilizada como templo activo. Lejos de ser demolida, la vieja catedral fue preservada como monumento histórico y cultural, convirtiéndose en uno de los símbolos más icónicos de Managua. Sus torres y cúpulas deterioradas narran la historia de una ciudad que fue destruida y renació de sus cenizas, siendo visitada por turistas nacionales e internacionales que llegan a contemplar este testigo silencioso de la historia nicaragüense.', 'https://images.unsplash.com/photo-1590856029192-284cc8461706?w=900&h=550&fit=crop&auto=format', 'https://images.unsplash.com/photo-1590856029192-284cc8461706?w=500&h=300&fit=crop&auto=format', 'https://www.youtube.com/watch?v=ZpEuJw-XH3I', '{"Historia","Terremoto 1972","Monumento","Patrimonio"}') ON CONFLICT (id) DO UPDATE SET department_id = EXCLUDED.department_id, name = EXCLUDED.name, category = EXCLUDED.category, description = EXCLUDED.description, history = EXCLUDED.history, cover_image_url = EXCLUDED.cover_image_url, thumbnail_image_url = EXCLUDED.thumbnail_image_url, video_url = EXCLUDED.video_url, tags = EXCLUDED.tags;
INSERT INTO tourist_sites (id, department_id, name, category, description, history, cover_image_url, thumbnail_image_url, video_url, tags) VALUES ('malecon-managua', 'managua', 'Malecón de Managua', 'turistico', 'Paseo costero renovado a orillas del Lago Xolotlán con monumentos nacionales, la estatua del Guerrero Negro y vistas al Volcán Momotombo al atardecer.', 'El Malecón de Managua, también conocido como Puerto Salvador Allende, es un paseo lacustre construido en las riberas del Lago Xolotlán (Lago de Managua). Inaugurado en 2008, el complejo fue desarrollado sobre una zona que durante décadas estuvo contaminada y deteriorada debido al terremoto de 1972 y décadas de descuido ambiental. El proyecto implicó una importante limpieza ambiental del lago y la construcción de infraestructura turística y recreativa. El malecón alberga restaurantes, bares, tiendas de artesanías y espacios de entretenimiento, así como el famoso monumento al Guerrero Negro y vistas impresionantes hacia el volcán Momotombo. Es el punto de encuentro más popular de la capital para residentes y visitantes, especialmente durante las tardes y fines de semana.', 'https://images.unsplash.com/photo-1711042927311-8e1823758d10?w=900&h=550&fit=crop&auto=format', 'https://images.unsplash.com/photo-1711042927311-8e1823758d10?w=500&h=300&fit=crop&auto=format', 'https://www.youtube.com/watch?v=dXKdaVKfJ38', '{"Lagos","Recreación","Atardecer","Gastronomía"}') ON CONFLICT (id) DO UPDATE SET department_id = EXCLUDED.department_id, name = EXCLUDED.name, category = EXCLUDED.category, description = EXCLUDED.description, history = EXCLUDED.history, cover_image_url = EXCLUDED.cover_image_url, thumbnail_image_url = EXCLUDED.thumbnail_image_url, video_url = EXCLUDED.video_url, tags = EXCLUDED.tags;
INSERT INTO tourist_sites (id, department_id, name, category, description, history, cover_image_url, thumbnail_image_url, video_url, tags) VALUES ('volcan-masaya', 'masaya', 'Volcán Masaya', 'turistico', 'Uno de los volcanes más activos del mundo con un lago de lava visible desde el borde del cráter. Primer Parque Nacional de Nicaragua establecido en 1979.', 'El Volcán Masaya es uno de los volcanes más activos del mundo y el único en Nicaragua con un lago de lava permanentemente activo visible a simple vista. Los indígenas Chorotegas que habitaban la región lo llamaban ''Popogatepe'' (montaña que arde) y lo consideraban morada de sus dioses. En el siglo XVI, los conquistadores españoles quedaron tan impresionados por la laguna de lava ardiente que el sacerdote franciscano Fray Blas del Castillo intentó descender al cráter en busca de oro. Los españoles colocaron una cruz en el borde del cráter, que aún se puede ver hoy, creyendo que era la boca del infierno. El Parque Nacional Volcán Masaya, establecido en 1979, fue el primer parque nacional de Nicaragua y recibe más de 200,000 visitantes al año. En tiempos recientes, la actividad volcánica ha aumentado con erupciones de ceniza y el lago de lava ha crecido significativamente.', 'https://images.unsplash.com/photo-1675701142610-5d40c754a3b6?w=900&h=550&fit=crop&auto=format', 'https://images.unsplash.com/photo-1675701142610-5d40c754a3b6?w=500&h=300&fit=crop&auto=format', 'https://www.youtube.com/watch?v=T5_sMfSm-Q0', '{"Volcán Activo","Naturaleza","Parque Nacional","Lava"}') ON CONFLICT (id) DO UPDATE SET department_id = EXCLUDED.department_id, name = EXCLUDED.name, category = EXCLUDED.category, description = EXCLUDED.description, history = EXCLUDED.history, cover_image_url = EXCLUDED.cover_image_url, thumbnail_image_url = EXCLUDED.thumbnail_image_url, video_url = EXCLUDED.video_url, tags = EXCLUDED.tags;
INSERT INTO tourist_sites (id, department_id, name, category, description, history, cover_image_url, thumbnail_image_url, video_url, tags) VALUES ('mercado-artesanias-masaya', 'masaya', 'Mercado de Artesanías de Masaya', 'turistico', 'El mercado artesanal más grande de Centroamérica, instalado en un histórico edificio colonial del siglo XIX. Centro vivo de la cultura y el folklore nicaragüense.', 'El Mercado Nacional de Artesanías de Masaya, conocido popularmente como El Mercadito, está instalado en el antiguo Cuartel de la Ciudad, un edificio de estilo colonial construido a finales del siglo XIX. Masaya ha sido históricamente la capital artesanal de Nicaragua, con una tradición indígena de manufactura que se remonta a las culturas precolombinas Chorotegas y Niquiranos. En 1991, el edificio del antiguo cuartel fue transformado en mercado artesanal, rescatando así un inmueble histórico y creando un espacio único para que artesanos de todo el país exhiban y vendan sus creaciones. El mercado alberga más de 80 locales donde se comercializan hamacas, cuero repujado, cerámica, madera tallada, ropa típica, sombreros de palma y toda clase de objetos artesanales. Los festivales folklóricos que se realizan en su plaza interior son declarados Patrimonio Cultural Intangible de la Nación.', 'https://images.unsplash.com/photo-1584904558330-f9772a6778c5?w=900&h=550&fit=crop&auto=format', 'https://images.unsplash.com/photo-1584904558330-f9772a6778c5?w=500&h=300&fit=crop&auto=format', 'https://www.youtube.com/watch?v=3vEYYUuUJFk', '{"Artesanías","Cultura","Folklore","Compras"}') ON CONFLICT (id) DO UPDATE SET department_id = EXCLUDED.department_id, name = EXCLUDED.name, category = EXCLUDED.category, description = EXCLUDED.description, history = EXCLUDED.history, cover_image_url = EXCLUDED.cover_image_url, thumbnail_image_url = EXCLUDED.thumbnail_image_url, video_url = EXCLUDED.video_url, tags = EXCLUDED.tags;
INSERT INTO tourist_sites (id, department_id, name, category, description, history, cover_image_url, thumbnail_image_url, video_url, tags) VALUES ('isla-ometepe', 'rivas', 'Isla de Ometepe', 'turistico', 'La isla más grande del mundo dentro de un lago de agua dulce, formada por dos volcanes gemelos: Concepción y Maderas. Reserva de Biósfera UNESCO desde 2010.', 'La Isla de Ometepe, cuyo nombre en náhuatl significa ''lugar de dos cerros'', es la isla lacustre más grande del mundo formada por volcanes dentro de un lago de agua dulce. Ubicada en el Gran Lago de Nicaragua (Cocibolca), la isla está formada por los volcanes gemelos Concepción (1,610 metros) activo, y Maderas (1,394 metros) inactivo con su propia laguna en la cima. La isla fue habitada durante milenios por pueblos indígenas que dejaron miles de petroglifos y estatuas de piedra que aún pueden encontrarse por toda la isla. En 2010, la UNESCO la declaró Reserva de Biósfera por su extraordinaria biodiversidad y riqueza arqueológica. Ometepe alberga cinco comunidades con una fuerte identidad cultural y una economía basada en agricultura orgánica, ganadería y ecoturismo. La isla es accesible en ferry desde el puerto de San Jorge en Rivas.', 'https://images.unsplash.com/photo-1710788206590-a8bbd6007e12?w=900&h=550&fit=crop&auto=format', 'https://images.unsplash.com/photo-1710788206590-a8bbd6007e12?w=500&h=300&fit=crop&auto=format', 'https://www.youtube.com/watch?v=FiKV38Rop5E', '{"UNESCO","Volcanes","Ecoturismo","Lago Nicaragua","Petroglifos"}') ON CONFLICT (id) DO UPDATE SET department_id = EXCLUDED.department_id, name = EXCLUDED.name, category = EXCLUDED.category, description = EXCLUDED.description, history = EXCLUDED.history, cover_image_url = EXCLUDED.cover_image_url, thumbnail_image_url = EXCLUDED.thumbnail_image_url, video_url = EXCLUDED.video_url, tags = EXCLUDED.tags;
INSERT INTO tourist_sites (id, department_id, name, category, description, history, cover_image_url, thumbnail_image_url, video_url, tags) VALUES ('san-juan-del-sur', 'rivas', 'San Juan del Sur', 'turistico', 'El balneario más famoso de Nicaragua, con una bahía natural de aguas tranquilas rodeada de colinas, reconocida internacionalmente como destino de surf y turismo.', 'San Juan del Sur es un pequeño puerto pesquero convertido en uno de los destinos turísticos más populares de Nicaragua y Centroamérica. La bahía natural fue utilizada desde la época colonial como punto de paso entre el Pacífico y el Atlántico durante la época de la fiebre del oro californiana en el siglo XIX. Miles de buscadores de oro norteamericanos atravesaron Nicaragua por esta ruta como alternativa al peligroso paso por Panamá, gracias al sistema de tránsito organizado por el empresario Cornelius Vanderbilt. El acceso navegable por el Río San Juan y el Gran Lago hasta San Juan del Sur convirtió al pueblo en un punto estratégico del comercio internacional. Hoy, San Juan del Sur es conocida mundialmente por sus playas aptas para el surf, su animada vida nocturna y la famosa estatua del Cristo de la Misericordia (mirador) que domina la bahía desde las alturas.', 'https://images.unsplash.com/photo-1630583950725-49a792209459?w=900&h=550&fit=crop&auto=format', 'https://images.unsplash.com/photo-1630583950725-49a792209459?w=500&h=300&fit=crop&auto=format', 'https://www.youtube.com/watch?v=bPNDI0-fFRk', '{"Playa","Surf","Turismo","Bahía Natural"}') ON CONFLICT (id) DO UPDATE SET department_id = EXCLUDED.department_id, name = EXCLUDED.name, category = EXCLUDED.category, description = EXCLUDED.description, history = EXCLUDED.history, cover_image_url = EXCLUDED.cover_image_url, thumbnail_image_url = EXCLUDED.thumbnail_image_url, video_url = EXCLUDED.video_url, tags = EXCLUDED.tags;
INSERT INTO tourist_sites (id, department_id, name, category, description, history, cover_image_url, thumbnail_image_url, video_url, tags) VALUES ('ruta-del-cafe', 'matagalpa', 'Ruta del Café Matagalpa', 'turistico', 'Recorrido por las fincas cafetaleras de altura de Matagalpa y Jinotega, donde se produce el 60% del café de exportación de Nicaragua, considerado entre los mejores del mundo.', 'La región de Matagalpa ha sido el corazón cafetero de Nicaragua desde finales del siglo XIX, cuando inmigrantes alemanes y europeos introdujeron el cultivo del café arábica en sus fértiles montañas. Apellidos como Kühl, Lüthy y Grünwald dejaron una huella imborrable en el paisaje cultural y arquitectónico de la ciudad. Las condiciones geográficas de Matagalpa son ideales para el cultivo del café de especialidad: altitudes entre 900 y 1,500 metros sobre el nivel del mar, suelos volcánicos ricos en minerales, bosques nubosos que regulan la temperatura y lluvias bien distribuidas. El café nicaragüense de Matagalpa y Jinotega ha ganado múltiples premios internacionales y es reconocido por su acidez brillante, cuerpo equilibrado y notas de chocolate y frutas tropicales. La ruta del café ofrece visitas a fincas donde se puede observar todo el proceso del grano: desde la cosecha hasta el beneficiado y tostado.', 'https://images.unsplash.com/photo-1590856028965-5683c4b48ad0?w=900&h=550&fit=crop&auto=format', 'https://images.unsplash.com/photo-1590856028965-5683c4b48ad0?w=500&h=300&fit=crop&auto=format', 'https://www.youtube.com/watch?v=GHhiLOm4tEo', '{"Café","Ecoturismo","Montaña","Agroturismo","Bosque Nuboso"}') ON CONFLICT (id) DO UPDATE SET department_id = EXCLUDED.department_id, name = EXCLUDED.name, category = EXCLUDED.category, description = EXCLUDED.description, history = EXCLUDED.history, cover_image_url = EXCLUDED.cover_image_url, thumbnail_image_url = EXCLUDED.thumbnail_image_url, video_url = EXCLUDED.video_url, tags = EXCLUDED.tags;
INSERT INTO tourist_sites (id, department_id, name, category, description, history, cover_image_url, thumbnail_image_url, video_url, tags) VALUES ('canion-de-somoto', 'esteli', 'Cañón de Somoto', 'turistico', 'Espectacular formación geológica de 800 millones de años de antigüedad, con paredes de 150 metros de altura y un río de aguas cristalinas perfecto para tubing y canyoning.', 'El Cañón de Somoto, ubicado en el municipio de Somoto, departamento de Madriz, es una de las maravillas geológicas más impresionantes de América Central. Fue descubierto científicamente por investigadores del Museo de Historia Natural de Viena en 2004, aunque las comunidades indígenas locales conocían la existencia de la formación desde tiempos ancestrales y la consideraban un lugar sagrado. El cañón tiene una antigüedad de aproximadamente 800 millones de años y fue formado por la erosión del Río Coco (también conocido como Río Segovia o Wangki), el río más largo de América Central. Sus paredes de granito de hasta 150 metros de altura albergan una rica biodiversidad, incluyendo aves rapaces, murciélagos y vegetación riparia única. El cañón se extiende por unos 6 kilómetros y su recorrido a pie y a nado es uno de los atractivos más emocionantes del norte de Nicaragua.', 'https://images.unsplash.com/photo-1590856029192-284cc8461706?w=900&h=550&fit=crop&auto=format', 'https://images.unsplash.com/photo-1590856029192-284cc8461706?w=500&h=300&fit=crop&auto=format', 'https://www.youtube.com/watch?v=WpK-MInW72s', '{"Cañón","Aventura","Río","Geología","Tubing"}') ON CONFLICT (id) DO UPDATE SET department_id = EXCLUDED.department_id, name = EXCLUDED.name, category = EXCLUDED.category, description = EXCLUDED.description, history = EXCLUDED.history, cover_image_url = EXCLUDED.cover_image_url, thumbnail_image_url = EXCLUDED.thumbnail_image_url, video_url = EXCLUDED.video_url, tags = EXCLUDED.tags;
